public class Rectangle {
    private double width;            // field
    private double height;
    public Rectangle(double w, double h) { // constructor
        width = w; height = h;
    }
    public double findArea() {         // method
        return width * height;
    }
}

public Rectangle() { width = 1.0; height = 1.0; }
public Rectangle(double w, double h) { width = w; height = h; }

Rectangle r1 = new Rectangle();          // 1.0 x 1.0
Rectangle r2 = new Rectangle(10.0, 20.0); // 10 x 20

class Ticket {
    static int count = 0;   // shared
    int id;                 // per object
    Ticket() { count++; id = count; }
}
// main:
Ticket a = new Ticket();
Ticket b = new Ticket();
Ticket c = b;
Ticket d = new Ticket();
System.out.println(a.count + " " + Ticket.count + " " + a.id + " " + d.id);
